ALTER TABLE "audit_events" DROP CONSTRAINT "audit_event_type";--> statement-breakpoint
ALTER TABLE "audit_events" DROP CONSTRAINT "audit_event_shape";--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "suspended" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "audit_events" ADD CONSTRAINT "audit_event_type" CHECK ("audit_events"."event_type" IN ('auth.login.succeeded','auth.password.changed','auth.sessions.revoked','auth.abuse.threshold_reached','admin.category.created','admin.category.updated','admin.product.created','admin.product.updated','admin.product.published','admin.product.unpublished','admin.inventory.updated','admin.user.promoted','admin.user.demoted','admin.user.sessions_revoked','admin.user.suspended','admin.user.reactivated','order.completed'));--> statement-breakpoint
ALTER TABLE "audit_events" ADD CONSTRAINT "audit_event_shape" CHECK (("audit_events"."event_type" = 'auth.abuse.threshold_reached' AND "audit_events"."outcome" = 'THRESHOLD_REACHED' AND "audit_events"."actor_user_id" IS NULL AND "audit_events"."target_type" IS NULL AND "audit_events"."target_id" IS NULL) OR ("audit_events"."actor_user_id" IS NOT NULL AND "audit_events"."target_id" IS NOT NULL AND "audit_events"."target_type" IS NOT NULL AND (("audit_events"."event_type" IN ('auth.login.succeeded','auth.password.changed','auth.sessions.revoked') AND "audit_events"."target_type" = 'user' AND "audit_events"."target_id" = "audit_events"."actor_user_id" AND "audit_events"."outcome" = 'SUCCESS') OR ("audit_events"."event_type" IN ('admin.user.promoted','admin.user.demoted','admin.user.sessions_revoked','admin.user.suspended','admin.user.reactivated') AND "audit_events"."target_type" = 'user' AND "audit_events"."outcome" = 'SUCCESS') OR ("audit_events"."event_type" IN ('admin.category.created','admin.category.updated') AND "audit_events"."target_type" = 'category' AND "audit_events"."outcome" = 'SUCCESS') OR ("audit_events"."event_type" IN ('admin.product.created','admin.product.updated','admin.product.published','admin.product.unpublished') AND "audit_events"."target_type" = 'product' AND "audit_events"."outcome" = 'SUCCESS') OR ("audit_events"."event_type" = 'admin.inventory.updated' AND "audit_events"."target_type" = 'inventory' AND "audit_events"."outcome" = 'SUCCESS') OR ("audit_events"."event_type" = 'order.completed' AND "audit_events"."target_type" = 'order' AND "audit_events"."outcome" IN ('SUCCESS','FAILED')))));